 // `spec_map_page` preserves well-formedness for a page-aligned target.
 pub proof fn lemma_map_page_preserves_inv(v: IdentityMapView, page: int)
     requires
         v.inv(),
         spec_is_page_aligned(page),
     ensures
         v.spec_map_page(page).inv(),
